"""`relay new workflow|skill|connector`: the starting point for an extension (PRD 20).

Everything generated works untouched: it passes `relay validate` and its own test. That is what
makes the live extension test a matter of editing something that runs, not of starting from blank.
"""

from __future__ import annotations

import re
from pathlib import Path

from relay.config import REPO_ROOT

_NAME = re.compile(r"[a-z][a-z0-9_]{1,23}")

_WORKFLOW = """\
# Generated by `relay new workflow {name}`. Check it with `relay validate`.
#
# Add steps below. Each one is rule, connector, skill, human or wait (PRD 11.1):
#   - An `action` must be declared in definitions/policies/rbac.yaml.
#   - A rule's `uses` is a function in relay/rules/, registered in the worker.
#   - A human step for a reserved action needs the approver's role in `task.assignee_role`.
#     For example, needs: [notify_owner], action: employment.probation.confirm, assignee_role: manager.
name: {name}
version: 1
subject: employee
trigger: {{ event: {name}.requested }}
context:
  recipient: "trigger.recipient"
steps:
  - id: notify_owner
    kind: connector
    uses: notify.slack_dm
    action: documents.request
    inputs:
      recipient: "ctx.recipient"
      body: "'{title} has started.'"
"""

_POLICY_TEST = """\
# Generated by `relay new workflow {name}`. `relay policy test approvals` runs this.
# Add a case for each decision this workflow depends on, especially what must NOT be allowed.
pack: approvals
cases:
  - name: "{name}: the engine may perform its first step"
    request: {{ action: documents.request, actor: {{ type: system, id: engine, roles: [system] }} }}
    expect: {{ effect: ALLOW }}
"""

_SIMULATION_TEST = '''\
"""Generated by `relay new workflow {name}`. Runs the workflow on the real engine, with a fake clock
and an in-memory connector. Add a test for each path, including the failures."""

from __future__ import annotations

from collections.abc import Iterator

import pytest
from sqlalchemy import Engine as SAEngine
from sqlalchemy import create_engine
from sqlalchemy.orm import sessionmaker

from relay.config import REPO_ROOT
from relay.core.engine.engine import Engine
from relay.core.engine.ports import EngineDeps
from relay.core.policy import PolicyService
from relay.core.registry.store import DefinitionStore
from relay.db import models as m
from tests.simulation.harness import FakeClock, FakeConnector, clean

pytestmark = pytest.mark.db

WORKFLOW_FILE = REPO_ROOT / "definitions" / "workflows" / "{name}.v1.yaml"
WORKFLOW = WORKFLOW_FILE.read_text(encoding="utf-8")


@pytest.fixture(scope="module")
def sa_engine(db_url: str) -> Iterator[SAEngine]:
    engine = create_engine(db_url)
    yield engine
    engine.dispose()


def test_{name}_runs_to_completion(sa_engine: SAEngine) -> None:
    clean(sa_engine)
    notify = FakeConnector("notify", op_names=("slack_dm",))
    deps = EngineDeps(connectors={{"notify": notify}}, clock=FakeClock())  # type: ignore[dict-item]
    sessions = sessionmaker(bind=sa_engine, expire_on_commit=False)
    store = DefinitionStore()
    with sessions.begin() as s:
        store.register(s, WORKFLOW, policies=PolicyService().policies(s), deps=deps, actor="test")
    engine = Engine(sessions, deps, definitions=store)

    run_id = engine.start_run(
        "{name}",
        {{"recipient": "U1"}},
        actor="test",
        subject_id="e1",
    )
    engine.run_until_idle()

    with sessions() as s:
        run = s.get(m.WorkflowRun, run_id)
        assert run is not None
        assert run.status is m.RunStatus.COMPLETED
    assert notify.calls["slack_dm"] == 1
'''

