_CONNECTOR_MANIFEST = """\
# Generated by `relay new connector {name}`. No Python is needed: every endpoint shape lives here.
connector: {name}
version: 1
base_url: "${{RELAY_{upper}_URL:-http://localhost:9000}}"
health_path: /{name}/health
ops:
  create_item:
    side_effect: true
    method: POST
    path: /{name}/items
    # header: honours Idempotency-Key. reference_lookup: no protection, reconcile first.
    # natural_key: a repeat is a 409 (set `by` under reconcile to the key field).
    idempotency_mode: header
    inject_reference: true
    reconcile: {{ path: /{name}/items }}
    # Responses are stored unencrypted: keep only what workflows read, never sensitive fields.
    response_fields: []
  lookup:
    side_effect: false
    method: GET
    path: /{name}/items
"""

_CONNECTOR_TEST = '''\
"""Generated by `relay new connector {name}`. Point this at the real API's shapes as you learn them."""

from __future__ import annotations

import asyncio
from pathlib import Path

import httpx

from relay.config import REPO_ROOT
from relay.connectors.http import HttpConnector
from relay.connectors.manifest import load_manifest

MANIFEST = Path(REPO_ROOT / "definitions" / "connectors" / "{name}.yaml")


def test_{name}_call_sends_our_key_and_reconcile_finds_it() -> None:
    records: dict[str, dict[str, str]] = {{}}

    def handler(request: httpx.Request) -> httpx.Response:
        if request.method == "POST":
            key = request.headers["Idempotency-Key"]
            records[key] = {{"id": "1", "client_reference": key}}
            return httpx.Response(201, json=records[key])
        wanted = request.url.params["client_reference"]
        items = [r for r in records.values() if r["client_reference"] == wanted]
        return httpx.Response(200, json={{"items": items, "count": len(items)}})

    connector = HttpConnector(load_manifest(MANIFEST), httpx.MockTransport(handler))
    assert asyncio.run(connector.reconcile("create_item", "k1", {{}})) is None
    created = asyncio.run(connector.call("create_item", {{}}, idempotency_key="k1"))
    assert created.external_id == "1"
    found = asyncio.run(connector.reconcile("create_item", "k1", {{}}))
    assert found is not None
    assert found.reconciled is True
'''


class ScaffoldError(ValueError):
    """The name is unusable, or a file already exists."""


def _check_name(name: str) -> None:
    if not _NAME.fullmatch(name):
        raise ScaffoldError(
            f"{name!r} must be lower_snake_case, start with a letter and be at most 24 characters."
        )


def _title(name: str) -> str:
    return name.replace("_", " ").capitalize()


def _write(root: Path, files: dict[str, str]) -> list[Path]:
    paths = {root / relative: text for relative, text in files.items()}
    existing = [str(path) for path in paths if path.exists()]
    if existing:
        raise ScaffoldError(f"Already exists, so nothing was written: {existing[0]}")
    for path, text in paths.items():
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(text, encoding="utf-8", newline="\n")
    return list(paths)


def new_workflow(name: str, root: Path = REPO_ROOT) -> list[Path]:
    """Create a workflow, a policy test stub and a simulation test."""
    _check_name(name)
    values = {"name": name, "title": _title(name)}
    return _write(
        root,
        {
            f"definitions/workflows/{name}.v1.yaml": _WORKFLOW.format(**values),
            f"definitions/policies/tests/{name}.yaml": _POLICY_TEST.format(**values),
            f"tests/simulation/test_{name}.py": _SIMULATION_TEST.format(**values),
        },
    )


def new_skill(name: str, root: Path = REPO_ROOT) -> list[Path]:
    """Create a skill manifest, prompt, module, test and an empty eval set."""
    _check_name(name)
    class_name = "".join(part.capitalize() for part in name.split("_"))
    values = {"name": name, "title": _title(name), "class_name": class_name}
    return _write(
        root,
        {
            f"definitions/skills/{name}.yaml": _SKILL_MANIFEST.format(**values),
            f"definitions/prompts/{name}/v1.md": _SKILL_PROMPT.format(**values),
            f"relay/skills/{name}.py": _SKILL_MODULE.format(**values),
            f"tests/unit/test_skill_{name}.py": _SKILL_TEST.format(**values),
            f"evals/{name}/labelled.jsonl": "",
        },
    )


def new_connector(name: str, root: Path = REPO_ROOT) -> list[Path]:
    """Create a connector manifest and a contract test."""
    _check_name(name)
    values = {"name": name, "upper": name.upper()}
    return _write(
        root,
        {
            f"definitions/connectors/{name}.yaml": _CONNECTOR_MANIFEST.format(**values),
            f"tests/unit/test_connector_{name}.py": _CONNECTOR_TEST.format(**values),
        },
    )
